import os,datetime
for f in ['TASK_SPEC.md','toy.py','test_examples.py','.input/TASK.md','.input/AUTHORIZATION.md','.input/SOUL.md','.input/BASELINE.json','.input/PRE_PROMPT.txt','_reports']:
    try:
        st=os.stat(f)
        print(f, "mtime", datetime.datetime.fromtimestamp(st.st_mtime).isoformat(), "size", st.st_size)
    except Exception as e:
        print(f,"ERR",e)
print("reports dir entries:", os.listdir('_reports'))
PY

